miss = 0
for old, new in REPL:
    if old not in s:
        print("!! 未命中:", old[:60].replace("\n", "\\n"))
        miss += 1
        continue
    s = s.replace(old, new, 1)

P.write_text(s, encoding="utf-8")
after = len(s.encode("utf-8"))
print("替换 %d 条，未命中 %d 条" % (len(REPL), miss))
print("bytes: %d -> %d  (省 %d)" % (before, after, before - after))
